def normalise_path(raw: str, cwd: str, workspace: str) -> tuple[str, bool]:
    """Return (path, external). Inside the workspace the path is repo-relative and worktree
    prefixes are folded back onto the repo they mirror."""
    p = os.path.expanduser(raw)
    if not p.startswith("/"):
        p = posixpath.join(cwd or workspace, p)
    p = posixpath.normpath(p)
    prefix = workspace.rstrip("/") + "/"
    if p == workspace.rstrip("/"):
        return "", True
    if not p.startswith(prefix):
        home = os.path.expanduser("~")
