def _split_outside_quotes(cmd: str, pipes: bool) -> list[str]:
    """Split on && || ; and newlines (pipes=False) or on single | (pipes=True), outside quotes."""
    segs, buf, quote, i = [], [], None, 0
    while i < len(cmd):
        ch = cmd[i]
        if quote:
            buf.append(ch)
            if ch == "\\" and quote == '"' and i + 1 < len(cmd):
                buf.append(cmd[i + 1])
                i += 1
            elif ch == quote:
                quote = None
        elif ch in ("'", '"', "`"):
            quote = ch
            buf.append(ch)
        elif cmd.startswith("&&", i) or cmd.startswith("||", i):
            if not pipes:
                segs.append("".join(buf))
                buf = []
            else:
                buf.append(cmd[i:i + 2])
            i += 1
        elif (not pipes and ch in ";\n") or (pipes and ch == "|"):
            segs.append("".join(buf))
            buf = []
        else:
            buf.append(ch)
        i += 1
    segs.append("".join(buf))
    return [s.strip() for s in segs if s.strip()]


