def _looks_like_path(tok: str) -> bool:
    return bool(tok) and not tok.startswith("-") and ("/" in tok or PATH_EXT_RE.search(tok) is not None)


def parse_read_segment(tokens: list[str]) -> Optional[tuple[list[str], bool, Optional[int], Optional[int]]]:
    """If the segment is a file-reading command, return (paths, whole, start, end)."""
