        script = None
        i = 0
        while i < len(args):
            a = args[i]
            if a in ("-n", "--quiet", "--silent", "-u"):
                i += 1
                continue
            if a in ("-e", "--expression"):
                script = args[i + 1] if i + 1 < len(args) else None
                i += 2
