        else:
            whole = False
            start = min(r[0] for r in ranges)
            ends = [r[1] for r in ranges]
            end = None if any(e is None for e in ends) else max(ends)
    else:
        i = 0
        while i < len(args):
            a = args[i]
            if cmd == "head" and a in ("-n", "--lines") and i + 1 < len(args):
