                i += 2
                continue
            if cmd == "head" and re.match(r"^-\d+$", a):
                whole, start, end = False, 1, int(a[1:])
                i += 1
                continue
            if cmd == "head" and a in ("-c", "--bytes"):
                whole = False
                i += 2
