    """Doc reads and tools/ script invocations in one shell command string.

    A pipeline such as `nl -ba FILE | sed -n '1,80p'` counts as one ranged read of FILE:
    a later stage that carries a range but no path narrows the reads of earlier stages."""
    reads: list[DocRead] = []
    scripts: list[tuple[str, str]] = []
