    except StopIteration:
        return None
    if meta.get("type") != "session_meta":
        return None
    p = meta.get("payload", {})
    if not _in_workspace(p.get("cwd", ""), workspace):
        return None
    sid = p.get("id") or p.get("session_id") or os.path.basename(path)
    s = Session(id=sid, client="codex", path=path, cwd=p.get("cwd", ""), start=(p.get("timestamp") or "")[:16])
    s.title = index.get(sid, "")
    pending: dict[str, ToolCall] = {}
    seq = 0
    for r in it:
        seq += 1
        t = r.get("type")
        pl = r.get("payload") or {}
        pt = pl.get("type")
        if t == "turn_context":
            s.models[pl.get("model") or "?"] += 1
        elif t == "compacted":
            s.compactions += 1
            s.compaction_seqs.append(seq)
        elif t == "world_state":
            agents = (pl.get("state") or {}).get("agents_md")
            entries = agents if isinstance(agents, list) else [agents] if isinstance(agents, dict) else []
            for e in entries:
                d = e.get("directory") or ""
                rel, _ = normalise_path(posixpath.join(d, "AGENTS.md"), "", workspace)
                if rel and rel not in s.injected:
                    s.injected.append(rel)
        elif t == "event_msg":
            if pt == "task_started":
                s.ctx_window = pl.get("model_context_window") or s.ctx_window
            elif pt == "token_count":
                last = ((pl.get("info") or {}).get("last_token_usage") or {})
                s.max_ctx = max(s.max_ctx, last.get("input_tokens", 0) or 0)
            elif pt == "item_completed":
                item = pl.get("item") or {}
                kind = item.get("type")
                if kind == "UserMessage":
                    text = "".join(c.get("text", "") for c in item.get("content", []) if c.get("type") == "text")
                    text = _clean_user_text(text)
                    if text and not _is_harness_text(text):
                        s.turns.append(UserTurn(seq, len(s.turns) + 1, text))
                elif kind == "FileChange":
                    for raw in (item.get("changes") or {}):
                        rel, _ = normalise_path(raw, s.cwd, workspace)
                        if rel and rel not in s.patches:
                            s.patches.append(rel)
                elif kind == "SubAgentActivity":
                    tid = item.get("agent_thread_id")
                    if tid and tid not in s.sub_agents:
                        s.sub_agents.append(tid)
        elif t == "response_item":
            if pt == "custom_tool_call":
                source = pl.get("input") or ""
                call_id = pl.get("call_id")
                if "apply_patch" in source and "*** Begin Patch" in source:
                    call = ToolCall(seq, "patch", "apply_patch")
                    for raw in _PATCH_FILE_RE.findall(source):
                        rel, _ = normalise_path(raw, s.cwd, workspace)
                        if rel and rel not in s.patches:
                            s.patches.append(rel)
                else:
                    blocks = _codex_exec_blocks(source)
                    if blocks:
                        cmd = "\n".join(b[0] for b in blocks)
                        call = ToolCall(seq, "exec", "exec_command", cmd=cmd, workdir=blocks[0][1])
                        for c, wd in blocks:
                            reads, scripts = analyse_command(c, wd or s.cwd, workspace, seq)
                            call.reads.extend(reads)
                            s.scripts.extend(scripts)
                    else:
                        call = ToolCall(seq, "other", pl.get("name") or "custom")
                s.calls.append(call)
                if call_id:
                    pending[call_id] = call
            elif pt == "custom_tool_call_output":
                call = pending.pop(pl.get("call_id"), None)
                if call is not None:
                    out = pl.get("output")
                    if isinstance(out, list):
                        call.out_chars = sum(len(c.get("text", "")) for c in out if isinstance(c, dict))
                    elif isinstance(out, str):
                        call.out_chars = len(out)
            elif pt == "function_call":
                s.calls.append(ToolCall(seq, "other", pl.get("name") or "function"))
    return s


# Claude Code ---------------------------------------------------------------

_CONTINUATION = "This session is being continued from a previous conversation"


def read_claude_session(path: str, workspace: str) -> Optional[Session]:
    records = list(_json_lines(path))
    cwd = next((r.get("cwd") for r in records if r.get("cwd")), None)
    if not cwd or not _in_workspace(cwd, workspace):
        return None
    sid = next((r.get("sessionId") for r in records if r.get("sessionId")), os.path.splitext(os.path.basename(path))[0])
    s = Session(id=sid, client="claude-code", path=path, cwd=cwd)
    s.start = next((r.get("timestamp", "")[:16] for r in records if r.get("timestamp")), "")
    pending: dict[str, ToolCall] = {}
    for seq, r in enumerate(records, 1):
        t = r.get("type")
        if t == "ai-title" and r.get("title") and not s.title:
            s.title = r["title"]
        elif t == "attachment":
            a = r.get("attachment") or {}
            if a.get("type") == "nested_memory" and a.get("path"):
                rel, _ = normalise_path(a["path"], cwd, workspace)
                if rel and rel not in s.injected:
                    s.injected.append(rel)
        elif t in ("user", "assistant"):
            msg = r.get("message") or {}
            if r.get("isSidechain"):
                continue
            if t == "assistant":
                s.models[msg.get("model") or "?"] += 1
                u = msg.get("usage") or {}
                ctx = (u.get("input_tokens") or 0) + (u.get("cache_read_input_tokens") or 0) + (u.get("cache_creation_input_tokens") or 0)
                s.max_ctx = max(s.max_ctx, ctx)
                for b in msg.get("content") or []:
                    if not isinstance(b, dict) or b.get("type") != "tool_use":
                        continue
                    name = b.get("name") or "?"
                    inp = b.get("input") or {}
                    if name == "Bash":
                        cmd = inp.get("command", "")
                        call = ToolCall(seq, "exec", "Bash", cmd=cmd, workdir=cwd)
                        reads, scripts = analyse_command(cmd, cwd, workspace, seq)
                        call.reads.extend(reads)
                        s.scripts.extend(scripts)
                    elif name == "Read":
                        call = ToolCall(seq, "read", "Read")
                        rel, ext = normalise_path(inp.get("file_path", ""), cwd, workspace)
                        if rel:
                            off, lim = inp.get("offset"), inp.get("limit")
                            if off or lim:
                                start = int(off or 1)
                                end = start + int(lim) - 1 if lim else None
                                call.reads.append(DocRead(seq, rel, ext, False, start, end))
                            else:
                                call.reads.append(DocRead(seq, rel, ext, True))
                    elif name in ("Edit", "Write", "NotebookEdit", "MultiEdit"):
                        call = ToolCall(seq, "patch", name)
                        rel, _ = normalise_path(inp.get("file_path") or inp.get("notebook_path") or "", cwd, workspace)
                        if rel and rel not in s.patches:
                            s.patches.append(rel)
                    elif name == "Agent":
                        call = ToolCall(seq, "other", name)
                        s.sub_agents.append(b.get("id") or "agent")
                    else:
                        call = ToolCall(seq, "other", name)
                    s.calls.append(call)
                    if b.get("id"):
                        pending[b["id"]] = call
            else:
                if r.get("isMeta"):
                    continue
                content = msg.get("content")
                blocks = content if isinstance(content, list) else [{"type": "text", "text": content or ""}]
                for b in blocks:
                    if not isinstance(b, dict):
                        continue
                    if b.get("type") == "tool_result":
                        call = pending.pop(b.get("tool_use_id"), None)
                        if call is not None:
                            c = b.get("content")
                            call.out_chars = len(c) if isinstance(c, str) else sum(len(x.get("text", "")) for x in c if isinstance(x, dict)) if isinstance(c, list) else 0
                    elif b.get("type") == "text":
                        text = _clean_user_text(b.get("text") or "")
                        if not text or _is_harness_text(text):
                            continue
                        if text.startswith(_CONTINUATION):
                            s.compactions += 1
                            s.compaction_seqs.append(seq)
                            continue
                        s.turns.append(UserTurn(seq, len(s.turns) + 1, text))
    return s


# --------------------------------------------------------------------------- discovery


def default_roots() -> list[str]:
    home = os.path.expanduser("~")
    return [
        os.path.join(home, ".codex", "sessions"),
        os.path.join(home, ".codex", "archived_sessions"),
        os.path.join(home, ".claude", "projects"),
    ]


def discover(roots: list[str], workspace: str) -> list[Session]:
    sessions: list[Session] = []
    for root in roots:
        if not os.path.isdir(root):
            continue
        index = load_codex_index(root)
        for path in sorted(glob.glob(os.path.join(root, "**", "*.jsonl"), recursive=True)):
            if os.path.basename(path) == "session_index.jsonl":
                continue
            try:
                first = next(_json_lines(path), None)
            except OSError:
                continue
            if first is None:
                continue
            s = read_codex_session(path, workspace, index) if first.get("type") == "session_meta" else read_claude_session(path, workspace)
            if s is not None:
                sessions.append(s)
    seen = {}
    for s in sessions:  # a session id may exist under both sessions/ and archived_sessions/
        seen.setdefault(s.id, s)
    out = sorted(seen.values(), key=lambda s: s.start)
    # Sub-agent activity is recorded on both ends of a spawn, so the parent is the
    # earliest-started session that mentions the child and started before it.
    parents: dict[str, Session] = {}
    for candidate in out:
        for child in candidate.sub_agents:
            cs = seen.get(child)
            if cs is None or cs is candidate or candidate.start > cs.start:
                continue
            if child not in parents or candidate.start < parents[child].start:
                parents[child] = candidate

    def root(s: Session) -> Session:
        visited = {s.id}
        while s.id in parents and parents[s.id].id not in visited:
            s = parents[s.id]
            visited.add(s.id)
        return s

    for s in out:
        parent = parents.get(s.id)
        if parent is not None:
            s.parent = parent.id
            if not s.title:
                s.title = f"↳ sub-agent of {root(s).label[:30]}"
    return out


def filter_sessions(sessions: list[Session], since: str = "", until: str = "", include_all: bool = False) -> list[Session]:
    out = []
    for s in sessions:
        if since and s.start[:10] < since:
            continue
        if until and s.start[:10] > until:
            continue
        if not include_all and not s.is_work:
            continue
        out.append(s)
    return out


# --------------------------------------------------------------------------- repo facts


def tracked_docs(workspace: str) -> list[str]:
    docs: list[str] = []
    for repo, prefix in (("", ""), ("fgcNote", "fgcNote/"), ("fgcnote-sf6-mod", "fgcnote-sf6-mod/")):
        cwd = os.path.join(workspace, repo) if repo else workspace
        if not os.path.isdir(os.path.join(cwd, ".git")) and not os.path.isfile(os.path.join(cwd, ".git")):
            continue
        try:
            out = subprocess.run(["git", "-C", cwd, "ls-files", "-z", "--", "*.md"], capture_output=True, check=True).stdout
        except (subprocess.CalledProcessError, FileNotFoundError):
            continue
        for raw in out.decode("utf-8", errors="replace").split("\0"):
            if not raw:
                continue
            if not repo and raw.split("/", 1)[0] in FIRST_PARTY_REPOS + ("MMDK",):
                continue
            docs.append(prefix + raw)
    return sorted(set(docs))


def doc_type(rel: str) -> str:
    """Heuristic mapping onto the document types of docs/README.md."""
    name = os.path.basename(rel)
    parts = rel.split("/")
    if "/docs/kb/" in "/" + rel:
        return "kb"
    if "docs/records/" in rel:
        return "record"
    if "docs/plans/" in rel:
        return "plan"
    if "docs/drafts/" in rel:
        return "draft"
    if "docs/ideas/" in rel:
        return "idea"
    if rel.startswith("talks/"):
        return "talk"
    if any(k in rel for k in ("ux-audits", "ux-judge", "changelog", "docs/reference", "docs/brand", "docs/research", "/research/")):
        return "product-collection"
    if name in ("AGENTS.md", "CLAUDE.md"):
        return "entry"
    depth = len(parts) - (2 if parts[0] in FIRST_PARTY_REPOS else 1)
    if depth == 0:
        return "root-living"
    return "mirror"


def doc_sections(workspace: str, rel: str) -> Optional[list[tuple[int, int, str]]]:
    path = os.path.join(workspace, rel)
    if not os.path.isfile(path):
        return None
    with open(path, encoding="utf-8", errors="replace") as fh:
        lines = fh.read().splitlines()
    heads = [(i + 1, l) for i, l in enumerate(lines) if l.startswith("#")]
    if not heads:
        return [(1, len(lines), "(no headings)")]
    out = []
    for j, (ln, h) in enumerate(heads):
        end = heads[j + 1][0] - 1 if j + 1 < len(heads) else len(lines)
        out.append((ln, end, h))
    return out


# --------------------------------------------------------------------------- analysis


def docs_read_before(s: Session, seq: int) -> list[str]:
    seen: list[str] = []
    for r in s.doc_reads:
        if r.seq >= seq:
            break
        if r.path not in seen:
            seen.append(r.path)
    return seen


def read_order(s: Session) -> list[str]:
    return docs_read_before(s, sys.maxsize)


def attribute_output(sessions: list[Session]) -> collections.Counter:
    """Tool-output characters attributed to each doc, split evenly across docs of one call."""
    cost: collections.Counter = collections.Counter()
    for s in sessions:
        for c in s.calls:
            docs = sorted({r.path for r in c.reads if r.path.endswith(".md")})
            if docs and c.out_chars:
                for d in docs:
                    cost[d] += c.out_chars // len(docs)
    return cost


def section_heat(sessions: list[Session], workspace: str, rel: str) -> Optional[list[dict]]:
    sections = doc_sections(workspace, rel)
    if sections is None:
        return None
    n = sections[-1][1]
    line_hits = collections.Counter()
    whole = 0
    for s in sessions:
        for r in s.doc_reads:
            if r.path != rel:
                continue
            if r.whole:
                whole += 1
                continue
            a = r.start or 1
            b = r.end if r.end is not None else n
            for i in range(a, min(b, n) + 1):
                line_hits[i] += 1
    out = []
    for a, b, h in sections:
        out.append({"start": a, "end": b, "heading": h, "ranged": max((line_hits[i] for i in range(a, b + 1)), default=0), "whole": whole})
    return out


def reread_after_compaction(sessions: list[Session]) -> collections.Counter:
    c: collections.Counter = collections.Counter()
    for s in sessions:
        if not s.compaction_seqs:
            continue
        first = s.compaction_seqs[0]
        before = set(docs_read_before(s, first))
        for r in s.doc_reads:
            if r.seq > first and r.path in before:
                c[r.path] += 1
    return c


def build_report(sessions: list[Session], workspace: str, tracked: Optional[list[str]] = None, docs: Iterable[str] = (), top: int = 30, boot: int = 5) -> dict:
    tracked = tracked_docs(workspace) if tracked is None else tracked
    by_sessions: collections.Counter = collections.Counter()
    by_reads: collections.Counter = collections.Counter()
    for s in sessions:
        for d in set(r.path for r in s.doc_reads):
            by_sessions[d] += 1
        for r in s.doc_reads:
            by_reads[r.path] += 1
    cost = attribute_output(sessions)
    types: dict[str, dict] = collections.defaultdict(lambda: {"tracked": 0, "read": 0})
    for d in tracked:
        types[doc_type(d)]["tracked"] += 1
        if d in by_sessions:
            types[doc_type(d)]["read"] += 1
    scripts: collections.Counter = collections.Counter()
    script_sessions: dict[str, set] = collections.defaultdict(set)
    actions: collections.Counter = collections.Counter()
    for s in sessions:
        for name, action in s.scripts:
            scripts[name] += 1
            script_sessions[name].add(s.id)
            if action:
                actions[(name, action)] += 1
    injected_and_manual = [s for s in sessions if any(i in {r.path for r in s.doc_reads} for i in s.injected)]
    return {
        "workspace": workspace,
        "sessions": [session_row(s) for s in sessions],
        "clients": dict(collections.Counter(s.client for s in sessions)),
        "date_range": [sessions[0].start[:10], sessions[-1].start[:10]] if sessions else [],
        "doc_types": dict(types),
        "docs": [
            {"path": d, "type": doc_type(d), "sessions": by_sessions[d], "reads": by_reads[d], "chars": cost[d], "tracked": d in tracked}
            for d, _ in by_sessions.most_common(top)
        ],
        "bootstrap": [{"session": s.label, "start": s.start, "order": read_order(s)[:boot]} for s in sessions],
        "injected_and_manual": [s.label for s in injected_and_manual],
        "compaction": {
            "sessions": sum(1 for s in sessions if s.compactions),
            "rereads": reread_after_compaction(sessions).most_common(10),
        },
        "scripts": [{"script": k, "calls": v, "sessions": len(script_sessions[k])} for k, v in scripts.most_common()],
        "actions": [{"script": k[0], "action": k[1], "calls": v} for k, v in actions.most_common()],
        "never_read": [d for d in tracked if d not in by_sessions],
        "sections": {d: section_heat(sessions, workspace, d) for d in docs},
    }


def session_row(s: Session) -> dict:
    return {
        "id": s.id,
        "client": s.client,
        "title": s.label,
        "start": s.start,
        "turns": len(s.turns),
        "calls": sum(1 for c in s.calls if c.kind != "other"),
        "patches": len(s.patches),
        "doc_reads": len(s.doc_reads),
        "docs": len({r.path for r in s.doc_reads}),
        "max_ctx": s.max_ctx,
        "ctx_window": s.ctx_window,
        "compactions": s.compactions,
        "scope": s.repo_scope,
        "models": dict(s.models),
        "sub_agents": len(s.sub_agents),
        "parent": s.parent,
    }


# --------------------------------------------------------------------------- rendering


def _k(n: int) -> str:
    return f"{n // 1000}k" if n >= 1000 else str(n)


def _short(path: str) -> str:
    return path.replace("fgcnote-sf6-mod/", "mod/").replace("fgcNote/", "app/")


def render_sessions(sessions: list[Session]) -> str:
    lines = ["| start | client | title | turns | calls | patches | docs | max ctx | compact | scope |", "|---|---|---|---|---|---|---|---|---|---|"]
    for s in sessions:
        r = session_row(s)
        lines.append(f"| {r['start']} | {r['client']} | {r['title'][:40]} | {r['turns']} | {r['calls']} | {r['patches']} | {r['docs']} | {_k(r['max_ctx'])} | {r['compactions']} | {r['scope']} |")
    return "\n".join(lines)


def render_digest(s: Session, workspace: str, full: bool = False) -> str:
    out = [f"# {s.label}", ""]
    out.append(f"- id: `{s.id}` ({s.client}), start {s.start}, models {dict(s.models)}")
    out.append(f"- scope: {s.repo_scope}; turns {len(s.turns)}; tool calls {sum(1 for c in s.calls if c.kind != 'other')}; patches {len(s.patches)}; sub-agents {len(s.sub_agents)}")
    out.append(f"- context: max {_k(s.max_ctx)} of window {_k(s.ctx_window) if s.ctx_window else '?'}; compactions {s.compactions}")
    if s.injected:
        out.append(f"- injected by harness: {', '.join(s.injected)}")
    out.append("")
    out.append("## Docs read (in first-read order)")
    per_doc: dict[str, list[DocRead]] = collections.OrderedDict()
    for r in s.doc_reads:
        per_doc.setdefault(r.path, []).append(r)
    if not per_doc:
        out.append("(none)")
    for path, reads in per_doc.items():
        ranges = ["whole" if r.whole else f"L{r.start or 1}-{r.end if r.end is not None else '$'}" for r in reads]
        secs = doc_sections(workspace, path) if not any(r.external for r in reads) else None
        touched = []
        if secs:
            for a, b, h in secs:
                if any(r.whole or ((r.start or 1) <= b and (r.end if r.end is not None else secs[-1][1]) >= a) for r in reads):
                    touched.append(h.lstrip("# ").strip()[:40])
        out.append(f"- `{path}` ×{len(reads)} [{', '.join(ranges)}]" + (f" → {'; '.join(touched)}" if touched else ""))
    code = [r for r in s.reads if not r.path.endswith(".md")]
    out.append(f"\nNon-markdown reads: {len(code)} over {len({r.path for r in code})} files")
    if s.scripts:
        out.append("\n## Scripts")
        for (name, action), n in collections.Counter(s.scripts).most_common():
            out.append(f"- {name} {action} ×{n}")
    if s.patches:
        out.append("\n## Patched")
        for p in s.patches:
            out.append(f"- {p}")
    out.append("\n## User turns")
    for t in s.turns:
        text = t.text if full else t.text[:400].replace("\n", " ")
        before = docs_read_before(s, t.seq)
        out.append(f"\n[{t.index}] {text}")
        if t.index > 1:
            out.append(f"    docs read before: {', '.join(_short(d) for d in before) if before else '(none)'}")
    return "\n".join(out)


def render_turns(sessions: list[Session], full: bool = False, first: bool = False) -> str:
    out = []
    for s in sessions:
        turns = [t for t in s.turns if first or t.index > 1]
        if not turns:
            continue
        out.append(f"### {s.label}  ({s.client}, {s.start}, scope {s.repo_scope})")
        shown: list[str] = []
        for t in turns:
            text = t.text if full else t.text[:300].replace("\n", " ")
            before = docs_read_before(s, t.seq)
            new = [d for d in before if d not in shown]
            shown = before
            out.append(f"- [{t.index}] {text}")
            if t.index == 1 or new == before:
                out.append(f"  - read before: {', '.join(_short(d) for d in before) if before else '(none)'}")
            else:
                out.append(f"  - read since previous turn: {', '.join(_short(d) for d in new) if new else '(nothing new)'} ({len(before)} docs so far)")
        out.append("")
    return "\n".join(out)


def render_report(rep: dict) -> str:
    out = [f"# Context probe report", ""]
    out.append(f"workspace `{rep['workspace']}`; sessions {len(rep['sessions'])} ({rep['clients']}); dates {rep['date_range']}")
    out.append("\n## Sessions\n")
    out.append("| start | client | title | turns | calls | patches | docs | max ctx | compact | scope |")
    out.append("|---|---|---|---|---|---|---|---|---|---|")
    for r in rep["sessions"]:
        out.append(f"| {r['start']} | {r['client']} | {r['title'][:40]} | {r['turns']} | {r['calls']} | {r['patches']} | {r['docs']} | {_k(r['max_ctx'])} | {r['compactions']} | {r['scope']} |")
    out.append("\n## Tracked markdown by type (read by at least one session)\n")
    out.append("| type | tracked | read |")
    out.append("|---|---|---|")
    for k, v in sorted(rep["doc_types"].items(), key=lambda kv: -kv[1]["tracked"]):
        out.append(f"| {k} | {v['tracked']} | {v['read']} |")
    out.append("\n## Most-read docs\n")
    out.append("| sessions | reads | attributed chars | type | path |")
    out.append("|---|---|---|---|---|")
    for d in rep["docs"]:
        flag = "" if d["tracked"] else " (untracked)"
        out.append(f"| {d['sessions']} | {d['reads']} | {_k(d['chars'])} | {d['type']} | {d['path']}{flag} |")
    out.append("\n## First docs read per session\n")
    for b in rep["bootstrap"]:
        if b["order"]:
