def find_session(sessions: list[Session], key: str) -> Optional[Session]:
    for s in sessions:
        if s.id == key or s.id.startswith(key):
            return s
    hits = [s for s in sessions if key.lower() in s.label.lower()]
    primary = [s for s in hits if not s.parent]
    if len(primary) == 1:
        return primary[0]
    if len(hits) == 1:
        return hits[0]
    if len(hits) > 1:
        sys.stderr.write("ambiguous title, candidates:\n" + "\n".join(f"  {s.id}  {s.label}" for s in hits) + "\n")
    return None


def main(argv: Optional[list[str]] = None) -> int:
    common = argparse.ArgumentParser(add_help=False)
    common.add_argument("--root", action="append", help="transcript root(s); default: ~/.codex/sessions, ~/.codex/archived_sessions, ~/.claude/projects")
    common.add_argument("--workspace", help="main workspace checkout; default: git common dir of cwd")
    common.add_argument("--since", default="", help="YYYY-MM-DD inclusive")
    common.add_argument("--until", default="", help="YYYY-MM-DD inclusive")
    common.add_argument("--all", action="store_true", help="include sessions without tool calls (auto-review, chat-only)")
    common.add_argument("--json", action="store_true", help="machine-readable output")
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter, parents=[common])
    sub = ap.add_subparsers(dest="cmd", required=True)
    sub.add_parser("sessions", parents=[common])
    d = sub.add_parser("digest", parents=[common])
    d.add_argument("session", help="session id, id prefix or unique title substring")
    d.add_argument("--full", action="store_true", help="do not truncate user turns")
    t = sub.add_parser("turns", parents=[common])
    t.add_argument("--full", action="store_true")
    t.add_argument("--first", action="store_true", help="include the opening prompt of each session")
    r = sub.add_parser("report", parents=[common])
    r.add_argument("--doc", action="append", default=[], help="repo-relative markdown path for section heat (repeatable)")
    r.add_argument("--top", type=int, default=30)
    r.add_argument("--boot", type=int, default=5, help="how many first reads to show per session")
    args = ap.parse_args(argv)

    workspace = os.path.abspath(args.workspace) if args.workspace else detect_workspace()
    sessions = filter_sessions(discover(args.root or default_roots(), workspace), args.since, args.until, args.all)
    if not sessions:
        sys.stderr.write(f"no sessions for workspace {workspace}\n")
        return 1

    if args.cmd == "sessions":
        print(json.dumps([session_row(s) for s in sessions], ensure_ascii=False, indent=1) if args.json else render_sessions(sessions))
    elif args.cmd == "digest":
        s = find_session(sessions, args.session)
        if s is None:
            sys.stderr.write("session not found\n")
            return 1
        if args.json:
            row = session_row(s)
            row.update({"injected": s.injected, "patches": s.patches, "scripts": s.scripts,
                        "reads": [dataclasses.asdict(r) for r in s.reads],
                        "turns": [{"index": t.index, "text": t.text, "read_before": docs_read_before(s, t.seq)} for t in s.turns]})
            print(json.dumps(row, ensure_ascii=False, indent=1))
        else:
            print(render_digest(s, workspace, args.full))
    elif args.cmd == "turns":
        if args.json:
            rows = [{"session": s.label, "id": s.id, "client": s.client, "scope": s.repo_scope, "index": t.index, "text": t.text,
                     "read_before": docs_read_before(s, t.seq)} for s in sessions for t in s.turns if args.first or t.index > 1]
            print(json.dumps(rows, ensure_ascii=False, indent=1))
        else:
            print(render_turns(sessions, args.full, args.first))
    elif args.cmd == "report":
        rep = build_report(sessions, workspace, docs=args.doc, top=args.top, boot=args.boot)
        print(json.dumps(rep, ensure_ascii=False, indent=1) if args.json else render_report(rep))
    return 0


if __name__ == "__main__":
    try:
        code = main()
        sys.stdout.flush()
    except BrokenPipeError:  # e.g. piped into head
        os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
        code = 0
    sys.exit(code)

