def source_style(rel: str) -> Optional[str]:
    return SOURCE_STYLES.get(os.path.splitext(rel)[1].lower())


def _python_docstring_lines(text: str) -> set[int]:
    """Lines occupied by real module/class/function docstrings, when Python parses."""
    try:
        tree = ast.parse(text)
    except (SyntaxError, ValueError):
        return set()
    lines: set[int] = set()
    for node in ast.walk(tree):
        body = getattr(node, "body", None)
        if not isinstance(body, list) or not body:
            continue
        first = body[0]
        if not (isinstance(first, ast.Expr) and isinstance(first.value, ast.Constant)
                and isinstance(first.value.value, str)):
            continue
        start = getattr(first, "lineno", None)
        end = getattr(first, "end_lineno", start)
        if start is not None:
            lines.update(range(start, (end or start) + 1))
    return lines


def classify_source_lines(rel: str, text: str) -> tuple[list[str], list[str]]:
    """Return source lines and lower-bound line classes: blank, code, header, local.

    Only comment-only lines and Python docstrings count. Inline comments remain code, so
    ratios derived from this function deliberately understate comment content.
    """
    style = source_style(rel)
    lines = text.splitlines()
    if style is None:
        return lines, ["code" if line.strip() else "blank" for line in lines]
    docstrings = _python_docstring_lines(text) if rel.lower().endswith(".py") else set()
    kinds: list[str] = []
    in_block: Optional[str] = None
    seen_code = False
    for number, line in enumerate(lines, 1):
        stripped = line.strip()
        comment = False
        directive = number == 1 and stripped.startswith("#!")
        if not stripped:
            kinds.append("blank")
            continue
        if number in docstrings:
            comment = True
        elif in_block is not None:
            end_at = stripped.find(in_block)
            if end_at < 0:
                comment = True
            else:
                comment = not stripped[end_at + len(in_block):].strip()
                in_block = None
        elif style == "hash" and stripped.startswith("#") and not directive:
            comment = True
        elif style == "lua" and stripped.startswith("--"):
            long_open = re.match(r"--\[(=*)\[", stripped)
            if long_open:
                close = "]" + long_open.group(1) + "]"
                tail = stripped[long_open.end():]
                end_at = tail.find(close)
                if end_at < 0:
                    in_block = close
                    comment = True
                else:
                    comment = not tail[end_at + len(close):].strip()
            else:
                comment = True
        elif style == "slash":
            markers = [("/*", "*/"), ("<!--", "-->")]
            matched = next(((start, end) for start, end in markers if stripped.startswith(start)), None)
            if matched:
                start, end = matched
                end_at = stripped.find(end, len(start))
                if end_at < 0:
                    in_block = end
                    comment = True
                else:
                    comment = not stripped[end_at + len(end):].strip()
            elif stripped.startswith("//"):
                comment = True
        if comment:
            kinds.append("local" if seen_code else "header")
        else:
            kinds.append("code")
            if not directive:
                seen_code = True
    return lines, kinds


