def source_comment_report(sessions: list[Session], workspace: str, top: int = 30) -> dict:
    """Estimate comment-only content in source ranges using the current checkout.

    This intentionally measures inferred source ranges, not transcript output bytes. A read
    with no recoverable line range (for example plain `tail`) and a missing file are counted
    as unmeasured rather than guessed.
    """
    cache: dict[str, Optional[tuple[list[str], list[str]]]] = {}
    rows: dict[str, dict] = {}
    for s in sessions:
        for r in s.reads:
            if r.external or source_style(r.path) is None:
                continue
            row = rows.setdefault(r.path, {
                "path": r.path, "session_ids": set(), "reads": 0, "measured_reads": 0,
                "unmeasured_reads": 0, "lines": 0, "chars": 0, "comment_lines": 0,
                "comment_chars": 0, "header_lines": 0, "header_chars": 0,
                "local_lines": 0, "local_chars": 0,
            })
            row["session_ids"].add(s.id)
            row["reads"] += 1
            if r.path not in cache:
                path = os.path.join(workspace, r.path)
                try:
                    with open(path, encoding="utf-8", errors="replace") as fh:
                        cache[r.path] = classify_source_lines(r.path, fh.read())
                except OSError:
                    cache[r.path] = None
            classified = cache[r.path]
            if classified is None or (not r.whole and r.start is None and r.end is None):
                row["unmeasured_reads"] += 1
                continue
            lines, kinds = classified
            start = 1 if r.whole else (r.start or 1)
            end = len(lines) if r.whole or r.end is None else min(r.end, len(lines))
            if start > len(lines) or end < start:
                row["unmeasured_reads"] += 1
                continue
            row["measured_reads"] += 1
            for line, kind in zip(lines[start - 1:end], kinds[start - 1:end]):
                row["lines"] += 1
                row["chars"] += len(line)
                if kind in ("header", "local"):
                    row["comment_lines"] += 1
                    row["comment_chars"] += len(line)
                    row[kind + "_lines"] += 1
                    row[kind + "_chars"] += len(line)
    serial = []
    for row in rows.values():
        item = dict(row)
        item["sessions"] = len(item.pop("session_ids"))
        item["comment_percent"] = round(100 * item["comment_chars"] / item["chars"], 1) if item["chars"] else 0.0
        serial.append(item)
    serial.sort(key=lambda item: (-item["comment_chars"], -item["chars"], item["path"]))
    totals = {key: sum(row[key] for row in serial) for key in (
        "reads", "measured_reads", "unmeasured_reads", "lines", "chars",
        "comment_lines", "comment_chars", "header_lines", "header_chars",
        "local_lines", "local_chars",
    )}
    totals["files"] = len(serial)
    totals["comment_percent"] = round(100 * totals["comment_chars"] / totals["chars"], 1) if totals["chars"] else 0.0
    return {"summary": totals, "files": serial[:top]}


